cat > test-check.mjs << 'EOF'
import {ToolRegistry} from './dist/index.js';

const registry = new ToolRegistry();
registry.register(
  {
    name: 'test_tool',
    description: 'Test tool',
    inputSchema: {
      type: 'object',
      properties: {ssn: {type: 'string'}},
      required: ['ssn'],
    },
  },
  async () => 'unreachable'
);

const response = await registry.execute('test_tool', {ssn: 123456789});
console.log('Response result:', response.result);
console.log('Includes ssn:', response.result.includes('ssn'));
console.log('Includes string:', response.result.includes('string'));
console.log('Includes 123456789:', response.result.includes('123456789'));
EOF
npm run build 2>&1 | tail -5 && node test-check.mjs && rm test-check.mjs
